window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-0b73ed3f36e30017"]={"versions": [{"id": "FIG-0b73ed3f36e30017", "releases": ["R4.2.2"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> Datenstruktur- / Record-Layout-Diagramm (konzeptionelle/logische Blueprint-Sicht nach AUTOSAR-Metamodell).</li>\n<li><strong>Funktionale Einordnung:</strong> Definiert das normative logische Speicher- und Strukturmuster für eine eindimensionale Kennlinie mit festem, äquidistantem Achsenintervall (<strong><code>FixIntCur</code></strong> = <em>Fixed Interval Curve</em>). Es dient als Blueprint zur Spezifikation von <code>ApplicationDataType</code>s, <code>SwRecordLayout</code>s und <code>SwDataDefProps</code> in AUTOSAR Classic (gemäß <code>AUTOSAR_TR_GeneralBlueprintsSupplement</code>, Kapitel <em>Calibration Data / Record Layouts</em>), zur Parametrierung mathematischer Interpolationsroutinen (AUTOSAR <code>Bfx</code>) sowie zur standardisierten Generierung von ASAM MCD-2 MC (A2L)-Beschreibungsdateien für Kalibrierwerkzeuge (INCA, CANape).</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Gestrichelte Entitäten (Metadaten / Virtuelle Achsenparameter):</strong></li>\n<li><code>Nx</code>: Anzahl der Achsenstützstellen (Dimension der x-Achse). Gestrichelt modelliert, da dieser Wert zur Compile-Zeit als Metadatum bzw. Array-Größenkonstante festgelegt ist und typischerweise nicht als dynamisches Datum im ROM-Nutzdatenbereich abgelegt wird.</li>\n<li><code>Offset (x)</code>: Ursprungswert bzw. Anfangsstützstelle der x-Achse ($x_0$). Virtuell definiert, markiert die untere Bereichsgrenze.</li>\n<li><code>Shift (x)</code>: Schrittweitenfaktor der Stützstellendistanz (Intervallbreite $\\Delta x = 2^{\\text{Shift}(x)}$ oder fester Skalierungsabstand). Ermöglicht die äquidistante Stützstellenrekonstruktion über bitweise Schiebeoperationen ohne Fließkomma-Division.</li>\n<li><strong>Durchgezogene Entitäten (Nutzdaten-Array / Tabelle):</strong></li>\n<li>Spaltenvektor <code>[1]</code>, <code>[2]</code>, <code>[3]</code>, <code>..</code>, <code>[-1]</code>: Das physikalisch im Speicher (ROM/Flash bzw. Calibrated RAM) allokierte 1D-Wertearray der Ordinatenwerte ($Y$).</li>\n<li><code>[1]</code>: Erster Funktionswert an Stützstelle $x_0$.</li>\n<li><code>[-1]</code>: Letzter Funktionswert an Stützstelle $x_{Nx-1}$ (symbolisiert das Array-Endelement der Länge $N_x$).</li>\n<li><strong>Kardinalitäten & Relationen:</strong></li>\n<li>Streng 1:1-Zuordnung zwischen den $N_x$ virtuell errechneten x-Stützstellen und den $N_x$ persistent gespeicherten Ordinaten-Werten $[1 \\dots N_x]$.</li>\n<li>Die x-Achse existiert nicht als separates Stützstellen-Array im Speicher, sondern ist rein implizit über die Parametertripel $\\{N_x, \\text{Offset}(x), \\text{Shift}(x)\\}$ determiniert.</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf (Interpolationspfad)</h4>\n<ul class=\"fig-list\">\n<li><strong>Laufzeit-Zugriffsmuster (Deterministische $O(1)$-Interpolation, z. B. via <code>Bfx_Intrp1D</code>):</strong></li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Bereichsprüfung (Clipping/Limitation):</strong> Eingangswert $x_{\\text{in}}$ wird gegen die Intervallgrenzen geprüft:</li>\n</ol>\n<p class=\"fig-p\">$$x_{\\min} = \\text{Offset}(x), \\quad x_{\\max} = \\text{Offset}(x) + (N_x - 1) \\cdot 2^{\\text{Shift}(x)}$$</p>\n<ol class=\"fig-list\">\n<li><strong>Intervallbestimmung (Index Calculation):</strong></li>\n</ol>\n<p class=\"fig-p\">Berechnung des Basis-Index $k$ ohne iterative Suche (kein Binär- oder Intervall-Suchbaum erforderlich):</p>\n<p class=\"fig-p\">$$k = (x_{\\text{in}} - \\text{Offset}(x)) \\gg \\text{Shift}(x)$$</p>\n<ol class=\"fig-list\">\n<li><strong>Werteabruf:</strong> Direkter indizierter Speicherzugriff auf die benachbarten Ordinaten $y_k = \\text{Array}[k]$ und $y_{k+1} = \\text{Array}[k+1]$.</li>\n<li><strong>Lineare Interpolation:</strong> Berechnung des Zwischenwerts über die fraktionalen niederwertigen Bits von $(x_{\\text{in}} - \\text{Offset}(x))$ innerhalb des definierten Teilintervalls.</li>\n</ol>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Speicher- und Laufzeitvorteil (Embedded C):</strong></li>\n<li><strong>ROM/Flash-Reduktion:</strong> Erhebliche Einsparung von Flash-Speicher, da der Vektor der Abszissenwerte ($X$) entfällt.</li>\n<li><strong>Laufzeit-Determinismus:</strong> Feste Ausführungszeit ohne Worst-Case-Varianz durch binäre Stützstellensuche; prädestiniert für hochfrequente Regelschleifen (z. B. Motormanagement, Inverter-Ansteuerung).</li>\n<li><strong>ARXML-Modellierung:</strong></li>\n<li>Im Software-Component-Template (<code>SwRecordLayout</code>) muss der Bezeichner <code>FixIntCur</code> (bzw. die entsprechende Blueprint-Referenz) verknüpft sein.</li>\n<li>In <code>SwDataDefProps</code> wird die Achsenkonfiguration über die Kategorie <code>FIXED_AXIS</code> deklariert; <code>Offset</code> und <code>Shift</code> sind als Achsenattribute zu konfigurieren.</li>\n<li><strong>A2L-Generierung & Kalibriertools:</strong></li>\n<li>Der A2L-Postprozessor exportiert das Objekt als <code>CHARACTERISTIC</code> des Typs <code>VAL_BLK</code> oder als Kennlinie mit <code>AXIS_DESCR</code> / <code>FIX_AXIS_PAR_LIST</code>.</li>\n<li>Kalibrier-Tools sperren das Editieren von Einzel-x-Stützstellen im Editor und erlauben nur die Manipulation der Ordinatenwerte sowie globaler Offset-/Shift-Parameter.</li>\n</ul>"}, {"id": "FIG-d9b4bd62766d966d", "releases": ["R4.3.1", "R18-10_R4.4.0_R1.5.0", "R19-11", "R20-11", "R21-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> Datenstruktur- / Record-Layout-Diagramm (konzeptionelle/logische Blueprint-Sicht nach AUTOSAR-Metamodell).</li>\n<li><strong>Funktionale Einordnung:</strong> Definiert das normative logische Speicher- und Strukturmuster für eine eindimensionale Kennlinie mit festem, äquidistantem Achsenintervall (<strong><code>FixIntCur</code></strong> = <em>Fixed Interval Curve</em>). Es dient als Blueprint zur Spezifikation von <code>ApplicationDataType</code>s, <code>SwRecordLayout</code>s und <code>SwDataDefProps</code> in AUTOSAR Classic (gemäß <code>AUTOSAR_TR_GeneralBlueprintsSupplement</code>, Kapitel <em>Calibration Data / Record Layouts</em>), zur Parametrierung mathematischer Interpolationsroutinen (AUTOSAR <code>Bfx</code>) sowie zur standardisierten Generierung von ASAM MCD-2 MC (A2L)-Beschreibungsdateien für Kalibrierwerkzeuge (INCA, CANape).</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Gestrichelte Entitäten (Metadaten / Virtuelle Achsenparameter):</strong></li>\n<li><code>Nx</code>: Anzahl der Achsenstützstellen (Dimension der x-Achse). Gestrichelt modelliert, da dieser Wert zur Compile-Zeit als Metadatum bzw. Array-Größenkonstante festgelegt ist und typischerweise nicht als dynamisches Datum im ROM-Nutzdatenbereich abgelegt wird.</li>\n<li><code>Offset (x)</code>: Ursprungswert bzw. Anfangsstützstelle der x-Achse ($x_0$). Virtuell definiert, markiert die untere Bereichsgrenze.</li>\n<li><code>Shift (x)</code>: Schrittweitenfaktor der Stützstellendistanz (Intervallbreite $\\Delta x = 2^{\\text{Shift}(x)}$ oder fester Skalierungsabstand). Ermöglicht die äquidistante Stützstellenrekonstruktion über bitweise Schiebeoperationen ohne Fließkomma-Division.</li>\n<li><strong>Durchgezogene Entitäten (Nutzdaten-Array / Tabelle):</strong></li>\n<li>Spaltenvektor <code>[1]</code>, <code>[2]</code>, <code>[3]</code>, <code>..</code>, <code>[-1]</code>: Das physikalisch im Speicher (ROM/Flash bzw. Calibrated RAM) allokierte 1D-Wertearray der Ordinatenwerte ($Y$).</li>\n<li><code>[1]</code>: Erster Funktionswert an Stützstelle $x_0$.</li>\n<li><code>[-1]</code>: Letzter Funktionswert an Stützstelle $x_{Nx-1}$ (symbolisiert das Array-Endelement der Länge $N_x$).</li>\n<li><strong>Kardinalitäten & Relationen:</strong></li>\n<li>Streng 1:1-Zuordnung zwischen den $N_x$ virtuell errechneten x-Stützstellen und den $N_x$ persistent gespeicherten Ordinaten-Werten $[1 \\dots N_x]$.</li>\n<li>Die x-Achse existiert nicht als separates Stützstellen-Array im Speicher, sondern ist rein implizit über die Parametertripel $\\{N_x, \\text{Offset}(x), \\text{Shift}(x)\\}$ determiniert.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\">\n<li><strong>Laufzeit-Zugriffsmuster (Deterministische $O(1)$-Interpolation, z. B. via <code>Bfx_Intrp1D</code>):</strong></li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Bereichsprüfung (Clipping/Limitation):</strong> Eingangswert $x_{\\text{in}}$ wird gegen die Intervallgrenzen geprüft:</li>\n</ol>\n<p class=\"fig-p\">$$x_{\\min} = \\text{Offset}(x), \\quad x_{\\max} = \\text{Offset}(x) + (N_x - 1) \\cdot 2^{\\text{Shift}(x)}$$</p>\n<ol class=\"fig-list\">\n<li><strong>Intervallbestimmung (Index Calculation):</strong></li>\n</ol>\n<p class=\"fig-p\">Berechnung des Basis-Index $k$ ohne iterative Suche (kein Binär- oder Intervall-Suchbaum erforderlich):</p>\n<p class=\"fig-p\">$$k = (x_{\\text{in}} - \\text{Offset}(x)) \\gg \\text{Shift}(x)$$</p>\n<ol class=\"fig-list\">\n<li><strong>Werteabruf:</strong> Direkter indizierter Speicherzugriff auf die benachbarten Ordinaten $y_k = \\text{Array}[k]$ und $y_{k+1} = \\text{Array}[k+1]$.</li>\n<li><strong>Lineare Interpolation:</strong> Berechnung des Zwischenwerts über die fraktionalen niederwertigen Bits von $(x_{\\text{in}} - \\text{Offset}(x))$ innerhalb des definierten Teilintervalls.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Speicher- und Laufzeitvorteil (Embedded C):</strong></li>\n<li><strong>ROM/Flash-Reduktion:</strong> Erhebliche Einsparung von Flash-Speicher, da der Vektor der Abszissenwerte ($X$) entfällt.</li>\n<li><strong>Laufzeit-Determinismus:</strong> Feste Ausführungszeit ohne Worst-Case-Varianz durch binäre Stützstellensuche; prädestiniert für hochfrequente Regelschleifen (z. B. Motormanagement, Inverter-Ansteuerung).</li>\n<li><strong>ARXML-Modellierung:</strong></li>\n<li>Im Software-Component-Template (<code>SwRecordLayout</code>) muss der Bezeichner <code>FixIntCur</code> (bzw. die entsprechende Blueprint-Referenz) verknüpft sein.</li>\n<li>In <code>SwDataDefProps</code> wird die Achsenkonfiguration über die Kategorie <code>FIXED_AXIS</code> deklariert; <code>Offset</code> und <code>Shift</code> sind als Achsenattribute zu konfigurieren.</li>\n<li><strong>A2L-Generierung & Kalibriertools:</strong></li>\n<li>Der A2L-Postprozessor exportiert das Objekt als <code>CHARACTERISTIC</code> des Typs <code>VAL_BLK</code> oder als Kennlinie mit <code>AXIS_DESCR</code> / <code>FIX_AXIS_PAR_LIST</code>.</li>\n<li>Kalibrier-Tools sperren das Editieren von Einzel-x-Stützstellen im Editor und erlauben nur die Manipulation der Ordinatenwerte sowie globaler Offset-/Shift-Parameter.</li>\n</ul>"}, {"id": "FIG-9e8a7c299e858309", "releases": ["R22-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> Datenstruktur- / Record-Layout-Diagramm (konzeptionelle/logische Blueprint-Sicht nach AUTOSAR-Metamodell).</li>\n<li><strong>Funktionale Einordnung:</strong> Definiert das normative logische Speicher- und Strukturmuster für eine eindimensionale Kennlinie mit festem, äquidistantem Achsenintervall (<strong><code>FixIntCur</code></strong> = <em>Fixed Interval Curve</em>). Es dient als Blueprint zur Spezifikation von <code>ApplicationDataType</code>s, <code>SwRecordLayout</code>s und <code>SwDataDefProps</code> in AUTOSAR Classic (gemäß <code>AUTOSAR_TR_GeneralBlueprintsSupplement</code>, Kapitel <em>Calibration Data / Record Layouts</em>), zur Parametrierung mathematischer Interpolationsroutinen (AUTOSAR <code>Bfx</code>) sowie zur standardisierten Generierung von ASAM MCD-2 MC (A2L)-Beschreibungsdateien für Kalibrierwerkzeuge (INCA, CANape).</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Gestrichelte Entitäten (Metadaten / Virtuelle Achsenparameter):</strong></li>\n<li><code>Nx</code>: Anzahl der Achsenstützstellen (Dimension der x-Achse). Gestrichelt modelliert, da dieser Wert zur Compile-Zeit als Metadatum bzw. Array-Größenkonstante festgelegt ist und typischerweise nicht als dynamisches Datum im ROM-Nutzdatenbereich abgelegt wird.</li>\n<li><code>Offset (x)</code>: Ursprungswert bzw. Anfangsstützstelle der x-Achse ($x_0$). Virtuell definiert, markiert die untere Bereichsgrenze.</li>\n<li><code>Shift (x)</code>: Schrittweitenfaktor der Stützstellendistanz (Intervallbreite $\\Delta x = 2^{\\text{Shift}(x)}$ oder fester Skalierungsabstand). Ermöglicht die äquidistante Stützstellenrekonstruktion über bitweise Schiebeoperationen ohne Fließkomma-Division.</li>\n<li><strong>Durchgezogene Entitäten (Nutzdaten-Array / Tabelle):</strong></li>\n<li>Spaltenvektor <code>[1]</code>, <code>[2]</code>, <code>[3]</code>, <code>..</code>, <code>[-1]</code>: Das physikalisch im Speicher (ROM/Flash bzw. Calibrated RAM) allokierte 1D-Wertearray der Ordinatenwerte ($Y$).</li>\n<li><code>[1]</code>: Erster Funktionswert an Stützstelle $x_0$.</li>\n<li><code>[-1]</code>: Letzter Funktionswert an Stützstelle $x_{Nx-1}$ (symbolisiert das Array-Endelement der Länge $N_x$).</li>\n<li><strong>Kardinalitäten & Relationen:</strong></li>\n<li>Streng 1:1-Zuordnung zwischen den $N_x$ virtuell errechneten x-Stützstellen und den $N_x$ persistent gespeicherten Ordinaten-Werten $[1 \\dots N_x]$.</li>\n<li>Die x-Achse existiert nicht als separates Stützstellen-Array im Speicher, sondern ist rein implizit über die Parametertripel $\\{N_x, \\text{Offset}(x), \\text{Shift}(x)\\}$ determiniert.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\">\n<li><strong>Laufzeit-Zugriffsmuster (Deterministische $O(1)$-Interpolation, z. B. via <code>Bfx_Intrp1D</code>):</strong></li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Bereichsprüfung (Clipping/Limitation):</strong> Eingangswert $x_{\\text{in}}$ wird gegen die Intervallgrenzen geprüft:</li>\n</ol>\n<p class=\"fig-p\">$$x_{\\min} = \\text{Offset}(x), \\quad x_{\\max} = \\text{Offset}(x) + (N_x - 1) \\cdot 2^{\\text{Shift}(x)}$$</p>\n<ol class=\"fig-list\">\n<li><strong>Intervallbestimmung (Index Calculation):</strong></li>\n</ol>\n<p class=\"fig-p\">Berechnung des Basis-Index $k$ ohne iterative Suche (kein Binär- oder Intervall-Suchbaum erforderlich):</p>\n<p class=\"fig-p\">$$k = (x_{\\text{in}} - \\text{Offset}(x)) \\gg \\text{Shift}(x)$$</p>\n<ol class=\"fig-list\">\n<li><strong>Werteabruf:</strong> Direkter indizierter Speicherzugriff auf die benachbarten Ordinaten $y_k = \\text{Array}[k]$ und $y_{k+1} = \\text{Array}[k+1]$.</li>\n<li><strong>Lineare Interpolation:</strong> Berechnung des Zwischenwerts über die fraktionalen niederwertigen Bits von $(x_{\\text{in}} - \\text{Offset}(x))$ innerhalb des definierten Teilintervalls.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Speicher- und Laufzeitvorteil (Embedded C):</strong></li>\n<li><strong>ROM/Flash-Reduktion:</strong> Erhebliche Einsparung von Flash-Speicher, da der Vektor der Abszissenwerte ($X$) entfällt.</li>\n<li><strong>Laufzeit-Determinismus:</strong> Feste Ausführungszeit ohne Worst-Case-Varianz durch binäre Stützstellensuche; prädestiniert für hochfrequente Regelschleifen (z. B. Motormanagement, Inverter-Ansteuerung).</li>\n<li><strong>ARXML-Modellierung:</strong></li>\n<li>Im Software-Component-Template (<code>SwRecordLayout</code>) muss der Bezeichner <code>FixIntCur</code> (bzw. die entsprechende Blueprint-Referenz) verknüpft sein.</li>\n<li>In <code>SwDataDefProps</code> wird die Achsenkonfiguration über die Kategorie <code>FIXED_AXIS</code> deklariert; <code>Offset</code> und <code>Shift</code> sind als Achsenattribute zu konfigurieren.</li>\n<li><strong>A2L-Generierung & Kalibriertools:</strong></li>\n<li>Der A2L-Postprozessor exportiert das Objekt als <code>CHARACTERISTIC</code> des Typs <code>VAL_BLK</code> oder als Kennlinie mit <code>AXIS_DESCR</code> / <code>FIX_AXIS_PAR_LIST</code>.</li>\n<li>Kalibrier-Tools sperren das Editieren von Einzel-x-Stützstellen im Editor und erlauben nur die Manipulation der Ordinatenwerte sowie globaler Offset-/Shift-Parameter.</li>\n</ul>"}, {"id": "FIG-108c221317e1ccc6", "releases": ["R23-11", "R24-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> Datenstruktur- / Record-Layout-Diagramm (konzeptionelle/logische Blueprint-Sicht nach AUTOSAR-Metamodell).</li>\n<li><strong>Funktionale Einordnung:</strong> Definiert das normative logische Speicher- und Strukturmuster für eine eindimensionale Kennlinie mit festem, äquidistantem Achsenintervall (<strong><code>FixIntCur</code></strong> = <em>Fixed Interval Curve</em>). Es dient als Blueprint zur Spezifikation von <code>ApplicationDataType</code>s, <code>SwRecordLayout</code>s und <code>SwDataDefProps</code> in AUTOSAR Classic (gemäß <code>AUTOSAR_TR_GeneralBlueprintsSupplement</code>, Kapitel <em>Calibration Data / Record Layouts</em>), zur Parametrierung mathematischer Interpolationsroutinen (AUTOSAR <code>Bfx</code>) sowie zur standardisierten Generierung von ASAM MCD-2 MC (A2L)-Beschreibungsdateien für Kalibrierwerkzeuge (INCA, CANape).</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Gestrichelte Entitäten (Metadaten / Virtuelle Achsenparameter):</strong></li>\n<li><code>Nx</code>: Anzahl der Achsenstützstellen (Dimension der x-Achse). Gestrichelt modelliert, da dieser Wert zur Compile-Zeit als Metadatum bzw. Array-Größenkonstante festgelegt ist und typischerweise nicht als dynamisches Datum im ROM-Nutzdatenbereich abgelegt wird.</li>\n<li><code>Offset (x)</code>: Ursprungswert bzw. Anfangsstützstelle der x-Achse ($x_0$). Virtuell definiert, markiert die untere Bereichsgrenze.</li>\n<li><code>Shift (x)</code>: Schrittweitenfaktor der Stützstellendistanz (Intervallbreite $\\Delta x = 2^{\\text{Shift}(x)}$ oder fester Skalierungsabstand). Ermöglicht die äquidistante Stützstellenrekonstruktion über bitweise Schiebeoperationen ohne Fließkomma-Division.</li>\n<li><strong>Durchgezogene Entitäten (Nutzdaten-Array / Tabelle):</strong></li>\n<li>Spaltenvektor <code>[1]</code>, <code>[2]</code>, <code>[3]</code>, <code>..</code>, <code>[-1]</code>: Das physikalisch im Speicher (ROM/Flash bzw. Calibrated RAM) allokierte 1D-Wertearray der Ordinatenwerte ($Y$).</li>\n<li><code>[1]</code>: Erster Funktionswert an Stützstelle $x_0$.</li>\n<li><code>[-1]</code>: Letzter Funktionswert an Stützstelle $x_{Nx-1}$ (symbolisiert das Array-Endelement der Länge $N_x$).</li>\n<li><strong>Kardinalitäten & Relationen:</strong></li>\n<li>Streng 1:1-Zuordnung zwischen den $N_x$ virtuell errechneten x-Stützstellen und den $N_x$ persistent gespeicherten Ordinaten-Werten $[1 \\dots N_x]$.</li>\n<li>Die x-Achse existiert nicht als separates Stützstellen-Array im Speicher, sondern ist rein implizit über die Parametertripel $\\{N_x, \\text{Offset}(x), \\text{Shift}(x)\\}$ determiniert.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\">\n<li><strong>Laufzeit-Zugriffsmuster (Deterministische $O(1)$-Interpolation, z. B. via <code>Bfx_Intrp1D</code>):</strong></li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Bereichsprüfung (Clipping/Limitation):</strong> Eingangswert $x_{\\text{in}}$ wird gegen die Intervallgrenzen geprüft:</li>\n</ol>\n<p class=\"fig-p\">$$x_{\\min} = \\text{Offset}(x), \\quad x_{\\max} = \\text{Offset}(x) + (N_x - 1) \\cdot 2^{\\text{Shift}(x)}$$</p>\n<ol class=\"fig-list\">\n<li><strong>Intervallbestimmung (Index Calculation):</strong></li>\n</ol>\n<p class=\"fig-p\">Berechnung des Basis-Index $k$ ohne iterative Suche (kein Binär- oder Intervall-Suchbaum erforderlich):</p>\n<p class=\"fig-p\">$$k = (x_{\\text{in}} - \\text{Offset}(x)) \\gg \\text{Shift}(x)$$</p>\n<ol class=\"fig-list\">\n<li><strong>Werteabruf:</strong> Direkter indizierter Speicherzugriff auf die benachbarten Ordinaten $y_k = \\text{Array}[k]$ und $y_{k+1} = \\text{Array}[k+1]$.</li>\n<li><strong>Lineare Interpolation:</strong> Berechnung des Zwischenwerts über die fraktionalen niederwertigen Bits von $(x_{\\text{in}} - \\text{Offset}(x))$ innerhalb des definierten Teilintervalls.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Speicher- und Laufzeitvorteil (Embedded C):</strong></li>\n<li><strong>ROM/Flash-Reduktion:</strong> Erhebliche Einsparung von Flash-Speicher, da der Vektor der Abszissenwerte ($X$) entfällt.</li>\n<li><strong>Laufzeit-Determinismus:</strong> Feste Ausführungszeit ohne Worst-Case-Varianz durch binäre Stützstellensuche; prädestiniert für hochfrequente Regelschleifen (z. B. Motormanagement, Inverter-Ansteuerung).</li>\n<li><strong>ARXML-Modellierung:</strong></li>\n<li>Im Software-Component-Template (<code>SwRecordLayout</code>) muss der Bezeichner <code>FixIntCur</code> (bzw. die entsprechende Blueprint-Referenz) verknüpft sein.</li>\n<li>In <code>SwDataDefProps</code> wird die Achsenkonfiguration über die Kategorie <code>FIXED_AXIS</code> deklariert; <code>Offset</code> und <code>Shift</code> sind als Achsenattribute zu konfigurieren.</li>\n<li><strong>A2L-Generierung & Kalibriertools:</strong></li>\n<li>Der A2L-Postprozessor exportiert das Objekt als <code>CHARACTERISTIC</code> des Typs <code>VAL_BLK</code> oder als Kennlinie mit <code>AXIS_DESCR</code> / <code>FIX_AXIS_PAR_LIST</code>.</li>\n<li>Kalibrier-Tools sperren das Editieren von Einzel-x-Stützstellen im Editor und erlauben nur die Manipulation der Ordinatenwerte sowie globaler Offset-/Shift-Parameter.</li>\n</ul>"}, {"id": "FIG-0ded82bc29124457", "releases": ["R25-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> Datenstruktur- / Record-Layout-Diagramm (konzeptionelle/logische Blueprint-Sicht nach AUTOSAR-Metamodell).</li>\n<li><strong>Funktionale Einordnung:</strong> Definiert das normative logische Speicher- und Strukturmuster für eine eindimensionale Kennlinie mit festem, äquidistantem Achsenintervall (<strong><code>FixIntCur</code></strong> = <em>Fixed Interval Curve</em>). Es dient als Blueprint zur Spezifikation von <code>ApplicationDataType</code>s, <code>SwRecordLayout</code>s und <code>SwDataDefProps</code> in AUTOSAR Classic (gemäß <code>AUTOSAR_TR_GeneralBlueprintsSupplement</code>, Kapitel <em>Calibration Data / Record Layouts</em>), zur Parametrierung mathematischer Interpolationsroutinen (AUTOSAR <code>Bfx</code>) sowie zur standardisierten Generierung von ASAM MCD-2 MC (A2L)-Beschreibungsdateien für Kalibrierwerkzeuge (INCA, CANape).</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Gestrichelte Entitäten (Metadaten / Virtuelle Achsenparameter):</strong></li>\n<li><code>Nx</code>: Anzahl der Achsenstützstellen (Dimension der x-Achse). Gestrichelt modelliert, da dieser Wert zur Compile-Zeit als Metadatum bzw. Array-Größenkonstante festgelegt ist und typischerweise nicht als dynamisches Datum im ROM-Nutzdatenbereich abgelegt wird.</li>\n<li><code>Offset (x)</code>: Ursprungswert bzw. Anfangsstützstelle der x-Achse ($x_0$). Virtuell definiert, markiert die untere Bereichsgrenze.</li>\n<li><code>Shift (x)</code>: Schrittweitenfaktor der Stützstellendistanz (Intervallbreite $\\Delta x = 2^{\\text{Shift}(x)}$ oder fester Skalierungsabstand). Ermöglicht die äquidistante Stützstellenrekonstruktion über bitweise Schiebeoperationen ohne Fließkomma-Division.</li>\n<li><strong>Durchgezogene Entitäten (Nutzdaten-Array / Tabelle):</strong></li>\n<li>Spaltenvektor <code>[1]</code>, <code>[2]</code>, <code>[3]</code>, <code>..</code>, <code>[-1]</code>: Das physikalisch im Speicher (ROM/Flash bzw. Calibrated RAM) allokierte 1D-Wertearray der Ordinatenwerte ($Y$).</li>\n<li><code>[1]</code>: Erster Funktionswert an Stützstelle $x_0$.</li>\n<li><code>[-1]</code>: Letzter Funktionswert an Stützstelle $x_{Nx-1}$ (symbolisiert das Array-Endelement der Länge $N_x$).</li>\n<li><strong>Kardinalitäten & Relationen:</strong></li>\n<li>Streng 1:1-Zuordnung zwischen den $N_x$ virtuell errechneten x-Stützstellen und den $N_x$ persistent gespeicherten Ordinaten-Werten $[1 \\dots N_x]$.</li>\n<li>Die x-Achse existiert nicht als separates Stützstellen-Array im Speicher, sondern ist rein implizit über die Parametertripel $\\{N_x, \\text{Offset}(x), \\text{Shift}(x)\\}$ determiniert.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\">\n<li><strong>Laufzeit-Zugriffsmuster (Deterministische $O(1)$-Interpolation, z. B. via <code>Bfx_Intrp1D</code>):</strong></li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Bereichsprüfung (Clipping/Limitation):</strong> Eingangswert $x_{\\text{in}}$ wird gegen die Intervallgrenzen geprüft:</li>\n</ol>\n<p class=\"fig-p\">$$x_{\\min} = \\text{Offset}(x), \\quad x_{\\max} = \\text{Offset}(x) + (N_x - 1) \\cdot 2^{\\text{Shift}(x)}$$</p>\n<ol class=\"fig-list\">\n<li><strong>Intervallbestimmung (Index Calculation):</strong></li>\n</ol>\n<p class=\"fig-p\">Berechnung des Basis-Index $k$ ohne iterative Suche (kein Binär- oder Intervall-Suchbaum erforderlich):</p>\n<p class=\"fig-p\">$$k = (x_{\\text{in}} - \\text{Offset}(x)) \\gg \\text{Shift}(x)$$</p>\n<ol class=\"fig-list\">\n<li><strong>Werteabruf:</strong> Direkter indizierter Speicherzugriff auf die benachbarten Ordinaten $y_k = \\text{Array}[k]$ und $y_{k+1} = \\text{Array}[k+1]$.</li>\n<li><strong>Lineare Interpolation:</strong> Berechnung des Zwischenwerts über die fraktionalen niederwertigen Bits von $(x_{\\text{in}} - \\text{Offset}(x))$ innerhalb des definierten Teilintervalls.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Speicher- und Laufzeitvorteil (Embedded C):</strong></li>\n<li><strong>ROM/Flash-Reduktion:</strong> Erhebliche Einsparung von Flash-Speicher, da der Vektor der Abszissenwerte ($X$) entfällt.</li>\n<li><strong>Laufzeit-Determinismus:</strong> Feste Ausführungszeit ohne Worst-Case-Varianz durch binäre Stützstellensuche; prädestiniert für hochfrequente Regelschleifen (z. B. Motormanagement, Inverter-Ansteuerung).</li>\n<li><strong>ARXML-Modellierung:</strong></li>\n<li>Im Software-Component-Template (<code>SwRecordLayout</code>) muss der Bezeichner <code>FixIntCur</code> (bzw. die entsprechende Blueprint-Referenz) verknüpft sein.</li>\n<li>In <code>SwDataDefProps</code> wird die Achsenkonfiguration über die Kategorie <code>FIXED_AXIS</code> deklariert; <code>Offset</code> und <code>Shift</code> sind als Achsenattribute zu konfigurieren.</li>\n<li><strong>A2L-Generierung & Kalibriertools:</strong></li>\n<li>Der A2L-Postprozessor exportiert das Objekt als <code>CHARACTERISTIC</code> des Typs <code>VAL_BLK</code> oder als Kennlinie mit <code>AXIS_DESCR</code> / <code>FIX_AXIS_PAR_LIST</code>.</li>\n<li>Kalibrier-Tools sperren das Editieren von Einzel-x-Stützstellen im Editor und erlauben nur die Manipulation der Ordinatenwerte sowie globaler Offset-/Shift-Parameter.</li>\n</ul>"}], "trans": [{"from": "FIG-0b73ed3f36e30017", "to": "FIG-d9b4bd62766d966d", "fr": "R4.2.2", "tr": "R4.3.1", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-d9b4bd62766d966d", "to": "FIG-9e8a7c299e858309", "fr": "R21-11", "tr": "R22-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-9e8a7c299e858309", "to": "FIG-108c221317e1ccc6", "fr": "R22-11", "tr": "R23-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-108c221317e1ccc6", "to": "FIG-0ded82bc29124457", "fr": "R24-11", "tr": "R25-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
